"""Independent structural consumer of actual P1 export; never source admission."""
import base64
import copy
import json
from pathlib import Path
import unittest
from tests.nba_s_family.test_statistical import pregame
from v2.nba_architecture.v2_contracts import seal
from v2.nba_s_family.model import SFError,canonical,digest
from v2.nba_s_family.p1_native import inspect_p1_export


class P1NativeTests(unittest.TestCase):
    def fixture(self):
        # Generated by actual P1 export_prior_game on its explicit synthetic fixture.
        return json.loads((Path(__file__).parent/'fixtures/p1_native_synthetic_v1.json').read_text())

    def pregame(self):
        p=pregame();p.update(training_cutoff_at='2022-11-01T00:00:00Z',input_freeze_at='2022-11-02T00:00:00Z',forecast_at='2022-11-02T00:01:00Z',event_start_at='2022-11-03T00:00:00Z',decision_local_date='2022-11-02')
        return seal({k:v for k,v in p.items() if k!='content_hash'})

    def inspect(self,x):return inspect_p1_export(x,pregame=self.pregame(),stat='points')

    def test_valid_structure_is_lossless_but_source_admission_blocked(self):
        x=self.fixture();r=self.inspect(x)
        self.assertEqual(r['status'],'BLOCKED');self.assertEqual(r['preserved_export'],x)
        self.assertEqual(r['denominator'],dict(attempted=1,structurally_checked=1,admitted=0,quarantined=1))
        self.assertEqual(r['training_rows'],[]);self.assertTrue(r['synthetic_compatibility_only'])
        self.assertIn('RETRIEVAL_AFTER_MODEL_TRAINING_CUTOFF',r['missing_requirements'])
        for stat in ('points','rebounds','assists','threes'):
            self.assertEqual(inspect_p1_export(x,pregame=self.pregame(),stat=stat)['status'],'BLOCKED')

    def test_corrupted_raw(self):
        x=self.fixture();x['evidence_bundle']['raw_base64']=base64.b64encode(b'corrupted').decode()
        with self.assertRaisesRegex(SFError,'P1_NATIVE_RAW_SHA_MISMATCH'):self.inspect(x)

    def test_corrupted_ancestor_and_orphan(self):
        x=self.fixture();old=copy.deepcopy(x['evidence_bundle']);x['evidence_bundle']['prior']=[old]
        c=x['evidence_bundle']['capture'];c.update(revision=2,supersedes_receipt_sha256=digest(canonical(old['capture'])),retrieved_at='2026-11-16T18:30:00Z')
        x['evidence_bundle']['prior'][0]['raw_base64']=base64.b64encode(b'corrupted').decode()
        with self.assertRaisesRegex(SFError,'P1_NATIVE_RAW_SHA_MISMATCH'):self.inspect(x)
        x=self.fixture();x['evidence_bundle']['capture']['revision']=2
        with self.assertRaisesRegex(SFError,'P1_NATIVE_REVISION_ANCESTRY'):self.inspect(x)

    def test_resealed_derived_identity_duration_stat_tampering(self):
        for key,value,reason in [('player_id','nba:player:999','PLAYER_TEAM'),('team_id','nba:team:999','PLAYER_TEAM'),('game_id','nba:game:0022200002','GAME_IDENTITY'),('overtime_periods',3,'DURATION_MISMATCH'),('exact_minutes',99,'EXACT_MINUTES_MISMATCH')]:
            x=self.fixture();x['exposure'][key]=value
            with self.subTest(key=key),self.assertRaisesRegex(SFError,reason):self.inspect(x)
        x=self.fixture();x['exposure']['stats']['points']+=1
        with self.assertRaisesRegex(SFError,'STAT_MISMATCH'):self.inspect(x)

    def test_optimistic_clocks_roles_or_admission_flags_cannot_enable_fit(self):
        for mutation in ('clock','role','status','denominator'):
            x=self.fixture()
            if mutation=='clock':x['clocks']['first_defensible_available_at']='2022-10-22T01:00:00Z'
            if mutation=='role':x['role']='wing'
            if mutation=='status':x['admission_status']='VERIFIED'
            if mutation=='denominator':x['candidate_denominator']['admitted']=1
            with self.subTest(mutation=mutation),self.assertRaises(SFError):self.inspect(x)

    def test_target_game_and_post_training_game_rejected(self):
        x=self.fixture();p=self.pregame();p['game_id']=x['exposure']['game_id'];p=seal({k:v for k,v in p.items() if k!='content_hash'})
        with self.assertRaisesRegex(SFError,'TARGET_OR_GAME_IDENTITY'):inspect_p1_export(x,pregame=p,stat='points')
        p=self.pregame();p['training_cutoff_at']='2022-10-20T00:00:00Z';p=seal({k:v for k,v in p.items() if k!='content_hash'})
        with self.assertRaisesRegex(SFError,'TRAINING_GAME_CUTOFF'):inspect_p1_export(x,pregame=p,stat='points')

if __name__=='__main__':unittest.main()

class ExactSourceMinuteTests(unittest.TestCase):
    fixture=P1NativeTests.fixture
    pregame=P1NativeTests.pregame
    inspect=P1NativeTests.inspect
    def minutes_export(self, exact, display):
        from v2.nba_s_family.model import canonical,digest
        x=self.fixture();b=x['evidence_bundle'];g=json.loads(base64.b64decode(b['raw_base64']))
        g['game']['homeTeam']['players'][0]['statistics']['minutes']=exact
        raw=canonical(g);b['raw_base64']=base64.b64encode(raw).decode();b['capture']['raw_sha256']=digest(raw)
        from decimal import Decimal
        import re
        m=re.fullmatch(r'PT(\d+)M(\d+(?:\.\d+)?)S',exact)
        value=float((Decimal(m[1])*60+Decimal(m[2]))/60)
        x['exposure'].update(raw_sha256=digest(raw),receipt_sha256=digest(canonical(b['capture'])),displayed_minutes=display,exact_minutes=value,accounting_status='ADJUDICATED_ROUNDED_SUBMINUTE' if display==0 else 'OFFICIAL_BOX_RECONCILED')
        return x

    def test_exact_raw_cap_fraction_not_erased_by_float_rounding(self):
        x=self.minutes_export('PT48M0.0000000000000001S',48)
        with self.assertRaisesRegex(SFError,'P1_NATIVE_EXPOSURE_PHYSICS'):self.inspect(x)

    def test_exact_raw_subminute_below_half_is_accepted_structurally(self):
        x=self.minutes_export('PT0M29.9999999999999999S',0)
        r=self.inspect(x);self.assertEqual(r['status'],'BLOCKED')
        self.assertEqual(r['denominator']['structurally_checked'],1)

    def test_exact_raw_cap_equality_positive(self):
        self.assertEqual(self.inspect(self.minutes_export('PT48M0S',48))['denominator']['structurally_checked'],1)

    def test_exact_half_minute_positive_zero_display_rejected(self):
        with self.assertRaisesRegex(SFError,'P1_NATIVE_ZERO_MINUTE_CREDIT_UNRESOLVED'):
            self.inspect(self.minutes_export('PT0M30S',0))

    def test_display_rounding_half_minute_boundary_is_exact(self):
        self.assertEqual(self.inspect(self.minutes_export('PT25M30S',26))['denominator']['structurally_checked'],1)
        with self.assertRaisesRegex(SFError,'P1_NATIVE_EXACT_MINUTES_MISMATCH'):
            self.inspect(self.minutes_export('PT25M29.9999999999999999S',26))

class NativeScalarTypeTests(unittest.TestCase):
    fixture=P1NativeTests.fixture
    pregame=P1NativeTests.pregame
    inspect=P1NativeTests.inspect

    def test_booleans_are_not_raw_counts_exact_exposure_or_denominators(self):
        for attack in ('raw_count','exact_minutes','denominator'):
            x=self.fixture()
            self.assertEqual(self.inspect(x)['denominator']['structurally_checked'],1)
            if attack=='raw_count':
                b=x['evidence_bundle'];g=json.loads(base64.b64decode(b['raw_base64']))
                g['game']['homeTeam']['players'][0]['statistics']['points']=True
                from v2.nba_s_family.model import canonical,digest
                raw=canonical(g);b['raw_base64']=base64.b64encode(raw).decode();b['capture']['raw_sha256']=digest(raw)
                x['exposure'].update(raw_sha256=digest(raw),receipt_sha256=digest(canonical(b['capture'])));x['exposure']['stats']['points']=1
            elif attack=='exact_minutes':
                x=ExactSourceMinuteTests().minutes_export('PT1M0S',1);x['exposure']['exact_minutes']=True
            else:x['candidate_denominator']={'attempted':True,'admitted':False,'quarantined':True}
            with self.subTest(attack=attack),self.assertRaises(SFError):self.inspect(x)

class NonparticipationSourceTests(unittest.TestCase):
    fixture=P1NativeTests.fixture
    pregame=P1NativeTests.pregame
    inspect=P1NativeTests.inspect

    def nonplayed(self,state,*,positive=False,played=None,minutes='PT0M0S'):
        x=self.fixture();b=x['evidence_bundle'];g=json.loads(base64.b64decode(b['raw_base64']))
        player=g['game']['homeTeam']['players'][0]
        player['played']=played if played is not None else ('0' if state=='dnp' else 'unknown')
        player['statistics']={'minutes':minutes,'points':11 if positive else 0,'reboundsTotal':0,'assists':0,'threePointersMade':0}
        from v2.nba_s_family.model import canonical,digest
        raw=canonical(g);b['raw_base64']=base64.b64encode(raw).decode();b['capture']['raw_sha256']=digest(raw)
        x['exposure'].update(raw_sha256=digest(raw),receipt_sha256=digest(canonical(b['capture'])),participation=state,displayed_minutes=None,exact_minutes=None,accounting_status='NONPARTICIPATION_OR_UNKNOWN',stats={})
        x['uncertainty']['participation']=state
        return x

    def test_nonplayed_positive_raw_credit_or_exposure_rejected(self):
        for state in ('dnp','unknown'):
            for positive,minutes in [(True,'PT0M0S'),(False,'PT0M0.0000000000000001S')]:
                with self.subTest(state=state,positive=positive,minutes=minutes),self.assertRaises(SFError):
                    self.inspect(self.nonplayed(state,positive=positive,minutes=minutes))

    def test_zero_raw_dnp_and_unknown_preserve_nulls_without_inventing_played_zero(self):
        for state in ('dnp','unknown'):
            x=self.nonplayed(state);r=self.inspect(x)
            self.assertEqual(r['status'],'BLOCKED');self.assertEqual(r['preserved_export']['exposure']['participation'],state)
            self.assertIsNone(r['preserved_export']['exposure']['exact_minutes'])
            self.assertIsNone(r['preserved_export']['exposure']['displayed_minutes'])
            self.assertEqual(r['preserved_export']['exposure']['stats'],{})

    def test_unknown_cannot_replace_explicit_raw_played_state(self):
        for played in ('0','1'):
            with self.subTest(played=played),self.assertRaises(SFError):
                self.inspect(self.nonplayed('unknown',played=played))

    def test_true_zero_positive_raw_credit_cannot_be_hidden_by_retained_stat_subset(self):
        x=self.nonplayed('unknown',positive=True,played='1')
        x['exposure'].update(participation='played',displayed_minutes=0,exact_minutes=0.,accounting_status='OFFICIAL_BOX_RECONCILED',stats={'threes':0})
        x['uncertainty']['participation']='played'
        with self.assertRaisesRegex(SFError,'ZERO_MINUTE_CREDIT_UNRESOLVED'):
            inspect_p1_export(x,pregame=self.pregame(),stat='threes')

class IntegerSourceAccountingTests(unittest.TestCase):
    fixture=P1NativeTests.fixture
    pregame=P1NativeTests.pregame
    inspect=P1NativeTests.inspect

    def raw_stats(self,stats):
        from v2.nba_s_family.model import canonical,digest
        from v2.nba_s_family.p1_native import STAT_KEYS
        x=self.fixture();b=x['evidence_bundle'];g=json.loads(base64.b64decode(b['raw_base64']))
        g['game']['homeTeam']['players'][0]['statistics']={'minutes':'PT26M0S',**stats}
        raw=canonical(g);b['raw_base64']=base64.b64encode(raw).decode();b['capture']['raw_sha256']=digest(raw)
        x['exposure'].update(raw_sha256=digest(raw),receipt_sha256=digest(canonical(b['capture'])),stats={k:stats[v] for k,v in STAT_KEYS.items() if v in stats})
        return x

    def test_integer_shooting_and_rebound_impossibilities_reject(self):
        cases=[dict(points=1,fieldGoalsAttempted=1,threePointersAttempted=0,freeThrowsMade=0),dict(points=2,fieldGoalsMade=1,threePointersMade=0,fieldGoalsAttempted=1,threePointersAttempted=1,freeThrowsMade=0),dict(points=11,reboundsTotal=1,reboundsOffensive=2)]
        for stats in cases:
            with self.subTest(stats=stats),self.assertRaises(SFError):self.inspect(self.raw_stats(stats))

    def test_sparse_missing_counts_stay_unknown_and_valid_integer_completion_passes(self):
        for stats in [dict(points=1,fieldGoalsAttempted=1,threePointersAttempted=0),dict(points=2,fieldGoalsAttempted=1,threePointersAttempted=0,freeThrowsMade=0),dict(points=11,reboundsTotal=2,reboundsOffensive=2)]:
            x=self.raw_stats(stats);r=self.inspect(x)
            self.assertEqual(r['status'],'BLOCKED');self.assertEqual(r['preserved_export']['exposure']['stats'],x['exposure']['stats'])
